syntax:
/* Storage class specifiers influencing variable linkage and lifetime */

auto int var;        // Automatic storage duration, local to block
static int var;      // Static storage duration, local to file or function
extern int var;      // External linkage, defined elsewhere
register int var;    // Hint to store in CPU register for faster access (deprecated in modern compilers)

/* Example of variable declaration with storage classes */
static int counter = 0;
extern int shared_resource;

code_example:
/* Static variable retains value across function calls, useful for state preservation */
void update_counter() {
    static int count = 0; // static storage duration, initialized once
    count++;
    printf("Counter: %d\n", count);
}
/* External variable declaration for sharing across multiple files */
extern int global_config;
/* Using register hint for performance-critical variable (modern compilers may ignore this) */
register int index = 0;
